    "sourceText": "【2024年4月1日基準の独自演習】藤田さんの2024年の給与所得は540万円。本人が保険料を負担した15年満期の平準払養老保険から満期一時金680万円を受け取り、正味払込保険料は560万円。他の一時所得はない。所得税の控除要件を満たす新契約の一般生命保険料12万円と新個人年金保険料10万円を支払い、介護医療保険料はない。生計を一にする配偶者の2024年の給与収入は70万円で、他の所得はない。配偶者は45歳、障害者ではなく、事業専従者でもない。",
