  "pr-kinzai2_life-007": {
    "sourceText": "【2024年4月1日基準の独自演習】青葉社は全役員・従業員を公平に対象とする2021年契約の養老保険（特約なし）に加入し、保険料負担者・契約者は会社、死亡保険金受取人は各人の遺族、満期保険金受取人は会社。年払保険料600万円は当期1年間の保障に対応する。代表者の役員在任期間は29年ちょうど、退職金4200万円。他の退職給付・過去年分との控除調整・障害退職はない。中退共による従業員の退職金準備も検討している。",
    "organization": "kinzai",
    "inputRows": [],
    "sentences": [
      "【2024年4月1日基準の独自演習】青葉社は全役員・従業員を公平に対象とする2021年契約の養老保険（特約なし）に加入し、保険料負担者・契約者は会社、死亡保険金受取人は各人の遺族、満期保険金受取人は会社。",
      "年払保険料600万円は当期1年間の保障に対応する。",
      "代表者の役員在任期間は29年ちょうど、退職金4200万円。",
      "他の退職給付・過去年分との控除調整・障害退職はない。",
      "中退共による従業員の退職金準備も検討している。"
    ]
  },
