    "sentences": [
      "【2024年4月1日基準の独自演習】遠藤さんの父は非上場の製造会社を経営し、株式の承継を検討している。",
      "本問では財産評価基本通達上の「中会社の小」、特定の評価会社には該当せず、原則的評価方式を用いる。",
      "資本金等の額を1株50円換算した比準要素は、自社／類似業種の順に配当6.5円／5円、利益32円／20円、簿価純資産260円／200円。",
      "類似業種株価600円。",
      "実際の1株当たり資本金等の額100円、純資産価額方式の1株評価額3000円。",
      "類似業種比準価額＝類似業種株価×3要素の比率の平均×0.6×（実際の1株資本金等の額／50円）。",
      "併用割合L＝0.6を採用する。",
      "中間計算の端数処理はせず最終値を求める。",
      "別途、父の相続人は妻と子2人、課税遺産総額は16000万円。",
      "速算表（取得額：税率／控除）は1,000万円以下10％／0、3,000万円以下15％／50万円、5,000万円以下20％／200万円、1億円以下30％／700万円。",
      "個別税額控除前を計算する。"
    ],
